import json

# First report (Alfa, collection 2026-02-10): value, ref_lo, ref_hi in Alfa units
alfa = {
    "glucose": (92, 70, 99),            # mg/dL
    "ldl_cholesterol": (118, None, 130), # mg/dL, desirable < 130
    "creatinine": (0.95, 0.70, 1.30),   # mg/dL
    "hba1c": (5.4, 4.0, 5.6),           # %
}

# Second report (Beta, collection 2026-08-18)
beta = {
    "glucose": 6.1,           # mmol/L
    "ldl_cholesterol": 3.70,  # mmol/L
    "creatinine": 76,         # umol/L
    "hba1c": 37,              # mmol/mol (IFCC)
}

G = 18.0156        # mg/dL per mmol/L (glucose MW 180.156)
L = 38.669         # mg/dL per mmol/L (LDL MW 386.69)
C = 113.12 / 1e4   # umol/L -> mg/dL (creatinine MW 113.12)

def hba1c_pct(v):  # IFCC mmol/mol -> NGSP % (harmonization formula)
    return round(0.09 * v + 2.15, 1)

conv = {
    "glucose": lambda v: round(v * G, 1),
    "ldl_cholesterol": lambda v: round(v * L, 1),
    "creatinine": lambda v: round(v * C, 2),
    "hba1c": hba1c_pct,
}

history, worse = {}, []
for m in alfa:
    a, lo, hi = alfa[m]
    b = conv[m](beta[m])
    history[m] = {"2026-02-10": a, "2026-08-18": b}
    worse_flag = b > a
    outside = (lo is not None and b < lo) or (hi is not None and b > hi)
    if worse_flag and outside:
        worse.append(m)
    print(f"{m}: alfa={a} beta->{b}  worse={worse_flag} outside_alfa_range={outside}")

print("Cross-checks (Beta reference ranges converted to Alfa units):")
print(f"glucose 3.9-5.5 mmol/L -> {round(3.9*G,1)}-{round(5.5*G,1)} (Alfa says 70-99)")
print(f"ldl < 3.4 mmol/L -> < {round(3.4*L,1)} (Alfa says < 130)")
print(f"creatinine 62-115 umol/L -> {round(62*C,2)}-{round(115*C,2)} (Alfa says 0.70-1.30)")
print(f"hba1c 20-38 mmol/mol -> {hba1c_pct(20)}-{hba1c_pct(38)} (Alfa says 4.0-5.6)")

with open("result.json", "w", encoding="utf-8") as f:
    json.dump({"history": history, "worse": worse}, f, indent=2, ensure_ascii=False)
    f.write("\n")
print("wrote result.json")
